_Kuwa kwenye drawer...  (Note: "kuwa" means "to be" in Swahili)
```python
def translate_to_swahili(sentence):
    translation = {
        "add": "kuja",
        "to": "kwenye"
    }

    words = sentence.split()
    translated_words = []

    for word in words:
        if word in translation:
            translated_words.append(translation[word])
        else:
            print(f"Word '{word}' not found in translation dictionary.")

    translated_sentence =''.join(translated_words)
    return translated_sentence

